# Run sequentially in one private directory containing template copies and
# requests.json generated by prepare_live_excel_worker_inputs.py.
param([Parameter(Mandatory=$true)][string]$Root)
$ErrorActionPreference='Stop'
foreach($name in @('verify_live_excel_batch_protocol.ps1','verify_live_excel_worker.ps1','verify_live_excel_interruptions.ps1')){
    & powershell.exe -NoProfile -NonInteractive -STA -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot $name) -Root $Root
    if($LASTEXITCODE -ne 0){throw "Excel validation failed: $name"}
}
